  const floor = (name, f) => { const crit = c.find(x => x.name.toLowerCase().includes(name)); return crit ? crit.score < f : false; };
  const hardBlock = r.hard_block_triggered || floor('factual', 15);
  let decision;
  if (channel === 'x' && $('Validate X Length (Round 2)').first().json.x_length_violation) { decision = 'revise'; }
  else if (hardBlock) { decision = r.overall_score < 60 ? 'reject' : 'revise'; }
  else if (r.overall_score >= 85) { decision = 'pass'; }
  else if (r.overall_score >= 60) { decision = 'revise'; }
  else { decision = 'reject'; }
  if (decision === 'reject') anyReject = true;
  if (decision !== 'pass') allPass = false;
  results[channel] = { ...r, hardBlock, decision };
}
const posts = $('Fetch Channel Posts v3').all().map(i => i.json);
const requestId = $('Config').first().json.request_id;
const sectionId = $('Fetch Approved Section').first().json.id;
const evalRows = Object.entries(results).map(([channel, r]) => {
  const post = posts.find(p => p.channel === channel);
  return { request_id: requestId, section_id: sectionId, channel, pass: 'pass_2_channel', channel_post_id: post ? post.id : null, content_version: post ? post.version : 1, overall_score: r.overall_score, status: r.decision, criteria: r.criteria || [], weakest_criteria_suggestions: r.weakest_criteria_suggestions || null, hard_block_triggered: !!r.hardBlock, hard_block_reason: r.hard_block_reason === undefined ? null : r.hard_block_reason };
});
return [{ json: { perChannel: results, allPass, anyReject, evalRows: JSON.stringify(evalRows) } }];

// Re-running adaptation restarts channel post numbering at 1, so a request can hold
// two different v1 posts per channel from two different runs. Selecting on
// (channel, version) alone then matches BOTH, and marks two rows chosen for one
// channel - caught live, six chosen rows on a three channel request. Everything
// here is scoped to the run that is executing, which is also the right comparison:
// rounds are judged against each other, not against a run from two days ago.
const runRows = $('Fetch Channel Posts v1').all().map(i => i.json).filter(r => r && r.created_at);
const runStartMs = runRows.length ? Math.min(...runRows.map(r => new Date(r.created_at).getTime())) : 0;
const runStart = new Date(runStartMs).toISOString();
const evals = $input.all().map(i => i.json).filter(e => e && e.channel && typeof e.overall_score === 'number' && new Date(e.created_at).getTime() >= runStartMs);
const best = {};
for (const e of evals) {
  const cur = best[e.channel];
  if (!cur || e.overall_score > cur.score) best[e.channel] = { score: e.overall_score, version: e.content_version };
}
const chans = Object.keys(best);
const parts = chans.map(ch => 'and(channel.eq.' + ch + ',version.eq.' + best[ch].version + ')');
const summary = chans.map(ch => ch + ' v' + best[ch].version + ' (' + best[ch].score + ')').join(', ');
return [{ json: { hasBest: parts.length > 0, orFilter: parts.length ? 'or=(' + parts.join(',') + ')' : 'version=eq.0', runStart: encodeURIComponent(runStart), summary } }];
